   const _dcMod = Math.max(0, _dcTgBase + _dcTgGear); // 1.2.178：体格有效值不低于0（装备负加成真的会扣修正）\n		      const _dcTotal = _dcRoll + _dcMod;\n		      const _dcRank = (_dcRoll >= 49) ? \"大成功\" : (_dcRoll <= 3) ? \"大失败\" : (_dcTotal >= 30) ? \"成功\" : \"失败\"; // 1.2.185：大失败=自然1/2/3（对齐卡内<检定约束>#5）\n		      /* 1.2.185：分档结算效果按卡内<体力判定规则>接线——大成功消耗归0、耗时减半（不足1分钟按1分钟计）；\n		         成功减免比例=池取下一颗骰÷100（1%~50%）；失败倍率=1+池取下一颗骰÷100（至多1.5倍）；\n		         大失败倍率=1+池取下一颗骰÷25（至多3倍）、耗时翻倍。实际消耗保留1位小数；减免/增大骰前端代掷仍用同一 d50 池。\n		         结果暂存 window._wsStaminaCheck 供剧情简报与结算补丁消费同一份数（结算读走即清；turns 对不上按无检定回退 1点/分钟原换算） */\n		      let _dcCost = _dcT, _dcMin = _dcT, _dcFx = \"无减免\";\n		      if (_dcT > 0) {\n		        const _dcNext = Math.floor(Math.random() * 50) + 1; // 减免/增大骰：池取下一颗（d50 同池）\n		        if (_dcRank === \"大成功\") {\n		          _dcCost = 0; _dcMin = Math.ceil(_dcT / 2);\n		          _dcFx = \"大成功消耗归0、耗时减半\";\n		        } else if (_dcRank === \"成功\") {\n		          const _dcRate = _dcNext / 100;\n		          _dcCost = Math.round(_dcT * (1 - _dcRate) * 10) / 10;\n		          _dcFx = \"减免\" + _dcNext + \"%（池取\" + _dcNext + \"÷100）\";\n		        } else if (_dcRank === \"失败\") {\n		          const _dcMul = 1 + _dcNext / 100;\n		          _dcCost = Math.round(_dcT * _dcMul * 10) / 10;\n		          _dcFx = \"增大至\" + _dcMul.toFixed(2) + \"倍（1+\" + _dcNext + \"÷100）\";\n		        } else {\n		          const _dcMul2 = 1 + _dcNext / 25;\n		          _dcCost = Math.round(_dcT * _dcMul2 * 10) / 10;\n		          _dcMin = _dcT * 2;\n		          _dcFx = \"增大至\" + _dcMul2.toFixed(2) + \"倍（1+\" + _dcNext + \"÷25）、耗时翻倍\";\n		        }\n		      }\n		      const _dcLeft = Math.max(0, Math.round((_dcHp - _dcCost) * 10) / 10); // 1.2.185：剩余按实际消耗算，保留1位小数\n		      try { window._wsStaminaCheck = { turns: _dcT, cost: _dcCost, minutes: _dcMin, rank: _dcRank }; } catch (eSc) {}\n		      // 1.2.178：物品效果段——逐条列出各装备槽「技能加成.体格」对本次检定的贡献；无涉及写「无」\n		      const _dcEq = (_dcG[\"装备\"] && typeof _dcG[\"装备\"] === \"object\") ? _dcG[\"装备\"] : {};\n		      const _dcGearTxt = Object.keys(_dcEq).map(function (sk) {\n		        const it = _dcEq[sk];\n		        if (!it || typeof it !== \"object\") return null;\n		        const gb = (it[\"技能加成\"] && typeof it[\"技能加成\"] === \"object\") ? Number(it[\"技能加成\"][\"体格\"]) : 0;\n		        if (!isFinite(gb) || gb === 0) return null; // 1.2.178：负加成也要如实列进物品效果段\n		        return (gearName(it) || sk) + \"·技能加成: 体格\" + (gb > 0 ? \"+\" : \"\") + gb + \" 计入修正\"; // 1.2.178：与面板同一套取名优先级（名称→name→外观），不再拿外观当名字\n		      }).filter(Boolean).join(\"；\") || \"无\";\n		      const _dcRoast = (data.castType === \"battleWin\") ? \"man!\" : \"mamba out\";\n		      return \"<DiceCheck>\\n\"\n		        + \"检定: 扛完这场对战（体格检定）\\n\"\n		        + \"骰运: 🎲 [\" + _dcRoll + \"](d50)+\" + _dcMod + \"(体格\" + _dcTgBase + (_dcTgGear !== 0 ? (_dcTgGear > 0 ? \"+装备\" : \"-装备\") + Math.abs(_dcTgGear) : \"\") + \")=\" + _dcTotal + \"\\n\"\n		        + \"结果: [\" + _dcRank + \"]（成功线30） -> 耗时\" + _dcMin + \"分钟；体力原消耗\" + _dcT + \"、实际消耗\" + _dcCost + \"（\" + _dcFx + \"）、剩余\" + _dcLeft + \"/\" + _dcHpMax + \"；物品效果: \" + _dcGearTxt + \"\\n\"\n		        + \"老大社的吐嘈: \" + _dcRoast + \"\\n\"\n		        + \"</DiceCheck>\\n\";\n		    } catch (eDc) { return \"\"; }\n		  })();\n		  const _btStory = _wsBuildStoryBrief(_btCd); // 必须在结算前拼：开局快照与写回前的旧变量此刻还完整；且在检定之后拼——简报里的耗时/体力消耗按检定减免结果报\n		  const _btFighters = _wsBorrowedFighters(_btCd || data); // 借用点名同样必须在结算前算：结算过程会清掉开局队伍快照\n		  const _btOps = _wsBuildBattleOps(_btCd, data.castType);\n		  // 羁绊变动明细随战斗报告诉 AI（谁掉/掉多少/为什么），读完即清防止带到下一场\n		  const _btBond = (window._wsBondNotes && window._wsBondNotes.length) ? \"\\n\\n【同伴羁绊变化，请一并叙述】\" + window._wsBondNotes.join(\"；\") : \"\";\n		  // 终端侧也轻提示一下（隐藏消息玩家看不到），只报\"谁从多少到多少\"，原因细节留给 AI\n		  if (window._wsBondNotes && window._wsBondNotes.length) {\n		    try { toast(\"同伴羁绊变化：\" + window._wsBondNotes.map(s => String(s).split(\"：\")[0]).join(\"，\"), \"warn\"); } catch (eT) {}\n		  }\n		  try { delete window._wsBondNotes; } catch (eBn) {}\n	